class Solution {
    private boolean win(String[] board, char p) {
        for (int r = 0; r < 3; r++) {
            if (board[r].charAt(0) == p && board[r].charAt(1) == p && board[r].charAt(2) == p) return true;
        }
        for (int c = 0; c < 3; c++) {
            if (board[0].charAt(c) == p && board[1].charAt(c) == p && board[2].charAt(c) == p) return true;
        }
        if (board[0].charAt(0) == p && board[1].charAt(1) == p && board[2].charAt(2) == p) return true;
        if (board[0].charAt(2) == p && board[1].charAt(1) == p && board[2].charAt(0) == p) return true;
        return false;
    }
    public boolean validTicTacToe(String[] board) {
        int xCount = 0, oCount = 0;
        for (String row : board) {
            for (int c = 0; c < 3; c++) {
                if (row.charAt(c) == 'X') xCount++;
                else if (row.charAt(c) == 'O') oCount++;
            }
        }
        if (oCount != xCount && oCount != xCount - 1) return false;
        boolean xWin = win(board, 'X');
        boolean oWin = win(board, 'O');
        if (xWin && oWin) return false;
        if (xWin && xCount != oCount + 1) return false;
        if (oWin && xCount != oCount) return false;
        return true;
    }
}

